<script setup lang="ts">export type ScheduleItem={id:string;title:string;start:string;end:string;resource?:string};const p=defineProps<{items:ScheduleItem[];resources?:string[]}>();const emit=defineEmits<{select:[id:string]}>();const rows=()=>p.resources?.length?p.resources:['Schedule'];const match=(resource:string)=>p.items.filter(i=>(i.resource||'Schedule')===resource)</script><template><section class="vx-scheduler"><div v-for="resource in rows()" :key="resource" class="vx-scheduler__row"><h4>{{resource}}</h4><div class="vx-scheduler__items"><button v-for="item in match(resource)" :key="item.id" type="button" @click="emit('select',item.id)"><strong>{{item.title}}</strong><small>{{item.start}} – {{item.end}}</small></button><span v-if="!match(resource).length">No events scheduled</span></div></div></section></template>
